#!/bin/bash

# Optimized Call of Duty: Black Ops launcher for NVIDIA GTX 1650
# Generated by Antigravity

# Set Wine prefix
WINEPREFIX="$HOME/Applications/CoD_BlackOps/bo_prefix"
export WINEPREFIX
export WINEARCH=win64

# --- CRITICAL: NVIDIA GPU FORCING ---
# For DX9 (OpenGL) and Vulkan games
export __NV_PRIME_RENDER_OFFLOAD=1
export __GLX_VENDOR_LIBRARY_NAME=nvidia
export __VK_LAYER_NV_optimus=NVIDIA_only
export DRI_PRIME=1

# --- DXVK Setup (The Magic Fix) ---
# Black Ops is DX9. Wihtout DXVK, it uses Wines OpenGL translator which is SLOW and often uses the wrong GPU.
# We Must ensure DXVK is installed in this prefix to convert DX9 -> Vulkan (which runs super fast on GTX 1650).
if [ ! -f "$WINEPREFIX/drive_c/windows/system32/d3d9.dll" ] || ! grep -q "Open Source" "$WINEPREFIX/drive_c/windows/system32/d3d9.dll" 2>/dev/null; then
    echo "DXVK not detected! Setting up DXVK for high performance..."
    mkdir -p "$WINEPREFIX"
    # Try using winetricks if available, else standard wine fallback (user might need to run: sudo apt install winetricks)
    if command -v winetricks &> /dev/null; then
        winetricks -q dxvk
    else
        echo "WARNING: winetricks not found. Game might run slow on OpenGL."
    fi
fi

# --- DXVK/Vulkan Settings ---
export DXVK_ASYNC=1
export DXVK_HUD=fps,gputoad  # Shows GPU load to verify it is using NVIDIA (should be > 0%)
export DXVK_STATE_CACHE=1
export DXVK_STATE_CACHE_PATH="$HOME/.cache/wine/blackops"

# --- Performance settings ---
export WINE_FULLSCREEN_FSR=1
export WINE_FULLSCREEN_FSR_STRENGTH=2
export __GL_THREADED_OPTIMIZATIONS=1
export WINEDEBUG=-all
export WINEESYNC=1
export WINEFSYNC=1
export WINEDLLOVERRIDES="nvapi,nvapi64=d"
export WINE_MOUSE_WARP_OVERRIDE=force

# Create necessary directories
mkdir -p "$HOME/.cache/wine/blackops"

# Change to game directory
GAME_DIR="/media/rohan/Game/Call of Duty - Black Ops/Call of Duty - Black Ops"
cd "$GAME_DIR" || { echo "Error: Game directory not found!"; exit 1; }

# Run the game
echo "Starting Call of Duty: Black Ops on NVIDIA GPU (Vulkan Mode)..."

# Use gamemoderun (if installed)
if command -v gamemoderun &> /dev/null; then
    LAUNCHER="gamemoderun"
else
    LAUNCHER=""
fi

# Launch
$LAUNCHER wine BlackOps.exe
